package main

import (
	"fmt"
	"math/rand"
	"strings"
)

// The std/deque corpus: a fixed sequence of operations run on a Go
// slice used as a double ended queue (the reference: a front pop is
// s = s[1:], a back pop s = s[:len(s)-1], a front push prepends), its
// answers written as the expected values of the same operations on an
// Xo Deque. The sequence crosses the ring's growth and wrap around
// several times.

func dequeCorpus() string {
	var o strings.Builder
	o.WriteString(`// Generated by scripts/stdcorpus from a Go slice model of a double ended
// queue. Do not edit: regenerate with go run ./scripts/stdcorpus.

use std/deque

fn show(x: Int?) -> Str {
  match x {
    Some(v) => "${v}"
    None => "none"
  }
}

test "an empty deque" {
  var d: deque.Deque[Int] = deque.new()
  expect(d.len()) == 0
  expect(d.is_empty()) == true
  expect(show(d.pop_front())) == "none"
  expect(show(d.pop_back())) == "none"
  expect(show(d.front())) == "none"
  expect(show(d.back())) == "none"
  expect(show(d.get(0))) == "none"
  expect(d.to_list()) == []
}

test "a copy shares until written (List's value semantics)" {
  var a: deque.Deque[Int] = deque.new(cap: 2)
  a.push_back(1)
  a.push_back(2)
  var b = a
  b.push_front(0)
  expect(a.to_list()) == [1, 2]
  expect(b.to_list()) == [0, 1, 2]
}

test "heap elements survive the ring's growth and wrap" {
  var d: deque.Deque[Str] = deque.new()
  for i in 0..20 {
    d.push_back("s${i}")
    let _ = d.pop_front()
    d.push_front("f${i}")
  }
  expect(d.len()) == 20
  expect(d.front()) == Some("f19")
  expect(d.back()) == Some("s19")
}
`)
	r := rand.New(rand.NewSource(430))
	for t := 0; t < 4; t++ {
		fmt.Fprintf(&o, "\ntest \"a slice model, sequence %d\" {\n  var d: deque.Deque[Int] = deque.new(cap: %d)\n", t, t)
		var s []int
		next := 0
		for k := 0; k < 120; k++ {
			switch op := r.Intn(10); {
			case op < 3:
				next++
				s = append(s, next)
				fmt.Fprintf(&o, "  d.push_back(%d)\n", next)
			case op < 5:
				next++
				s = append([]int{next}, s...)
				fmt.Fprintf(&o, "  d.push_front(%d)\n", next)
			case op < 7:
				want := "none"
				if len(s) > 0 {
					want = fmt.Sprint(s[0])
					s = s[1:]
				}
				fmt.Fprintf(&o, "  expect(show(d.pop_front())) == %q\n", want)
			case op < 9:
				want := "none"
				if len(s) > 0 {
					want = fmt.Sprint(s[len(s)-1])
					s = s[:len(s)-1]
				}
				fmt.Fprintf(&o, "  expect(show(d.pop_back())) == %q\n", want)
			default:
				i := r.Intn(len(s)+2) - 1
				want := "none"
				if i >= 0 && i < len(s) {
					want = fmt.Sprint(s[i])
				}
				fmt.Fprintf(&o, "  expect(show(d.get(%d))) == %q\n", i, want)
			}
		}
		parts := make([]string, len(s))
		for i, v := range s {
			parts[i] = fmt.Sprint(v)
		}
		fmt.Fprintf(&o, "  expect(d.len()) == %d\n  expect(d.to_list()) == [%s]\n}\n", len(s), strings.Join(parts, ", "))
	}
	return o.String()
}
